template:
otelcol.processor.tail_sampling "${1:default}" {
  output {
    metrics = []
    logs = []
    traces = []
  }
  policy {
    name = "${2}"
    type = "${3}"
  }
  debug_metrics {
    $0
  }

  // Exported fields:
